def topk(k, seq, key=None):
    """
    Find the k largest elements of a sequence.

    Operates lazily in n*log(k) time.

    Args:
        k: Number of largest elements to return
        seq: Iterable sequence to search through
        key: Function to extract comparison key from elements (default: None)

    Returns:
        A tuple of the k largest elements, sorted in descending order by key
    """
    if k <= 0:
        return ()

    if key is None:
        key = lambda x: x

    # Use a min-heap of size k to keep track of the k largest elements
    import heapq

    def get_key(item):
        return key(item)

    # Convert to list for processing if it's an iterator
    try:
        iter(seq)
    except TypeError:
        seq = [seq]

    # Use a heap to maintain the k largest elements
    heap = []

    for item in seq:
        item_key = get_key(item)
        if len(heap) < k:
            heapq.heappush(heap, (item_key, item))
        elif item_key > heap[0][0]:
            heapq.heapreplace(heap, (item_key, item))

    # Extract the elements from the heap (they are in order of key)
    result = [item for _, item in sorted(heap, key=lambda x: x[0], reverse=True)]

    # If k is 0, return empty tuple
    if k == 0:
        return ()

    # Return only the top k elements
    return tuple(result[:k])
