def pluck(ind, seqs, default=no_default):
    """Plucks an element or several elements from each item in a sequence.

    This is equivalent to running `map(curried.get(ind), seqs)`.

    Args:
        ind: A single index, string, or list of indices/strings.
        seqs: A sequence containing sequences or dicts.
        default: Default value to use when index is out of bounds or key is missing.

    Returns:
        A sequence of plucked elements, one per item in seqs.
    """
    from toolz import get

    def pluck_item(item):
        if isinstance(ind, list):
            return tuple(get(i, item, default) for i in ind)
        else:
            return get(ind, item, default)

    return (pluck_item(item) for item in seqs)

