def windowed_iter(src, size, fill=_UNSET):
    """Returns tuples with length *size* which represent a sliding window over iterable *src*.

    If *fill* is specified, it is used to fill in missing elements at the end of the windows.
    If *fill* is not specified, windows are only generated for complete sequences.
    """
    if size <= 0:
        return iter(())

    iterator = iter(src)
    window = []

    # Fill the initial window
    for _ in range(size):
        try:
            window.append(next(iterator))
        except StopIteration:
            break

    # If we didn't get enough elements, return early
    if len(window) < size:
        if fill is not _UNSET:
            # Pad with fill values
            while len(window) < size:
                window.append(fill)
        else:
            return iter([])

    # Yield the first complete window
    yield tuple(window)

    # Slide the window
    try:
        while True:
            # Move the window forward by one
            next_item = next(iterator)
            window.pop(0)
            window.append(next_item)
            yield tuple(window)
    except StopIteration:
        pass

    # Handle the case where we need to fill the remaining windows
    if fill is not _UNSET:
        # Reconstruct the iterator to handle the remaining elements
        it = iter(src)
        window = []
        for _ in range(size):
            try:
                window.append(next(it))
            except StopIteration:
                break

        # If we have a partial window, fill it with fill values
        if len(window) < size:
            while len(window) < size:
                window.append(fill)
            yield tuple(window)
