def is_arity(n, func, sigspec=None):
    """Does a function have only n positional arguments?

    This function relies on introspection and does not call the function.
    Returns None if validity can't be determined.
    """
    try:
        # Get the function's signature if available
        if hasattr(func, '__code__'):
            code = func.__code__
            if hasattr(code, 'co_argcount'):
                argcount = code.co_argcount
                # Check if the function has exactly n positional arguments
                # and no *args or **kwargs (which would make it have more than n)
                if argcount == n:
                    # Check if there are no *args or **kwargs
                    if code.co_flags & 0x04 == 0 and code.co_flags & 0x08 == 0:
                        return True
                    else:
                        return False
                elif argcount > n:
                    # If there are more than n positional arguments, check if they're all positional
                    # and if there are no *args or **kwargs
                    if code.co_flags & 0x04 == 0 and code.co_flags & 0x08 == 0:
                        return False
                    else:
                        return False
                else:
                    # If fewer than n positional arguments, it can't have exactly n
                    return False
        else:
